/*
 * A287308  Primes that can be generated by the concatenation in base 7, in
 *          ascending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287308
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th prime of the form k * 7^digit_count_base7(k+1) +
 *            (k+1), where k and k+1 are consecutive positive integers
 *            (base‑10)
 * Range:     u8 n <= 2, u16 n <= 36, u32 n <= 41, u64 n <= 41, u128 n <= 41,
 *            big any n
 * Helpers:   ensure_capacity, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n) {
    /* Static cache for memoisation */
    static seq_t *cache = NULL;          /* array of found primes */
    static size_t cap = 0;              /* capacity of cache */
    static idx_t len = 0;               /* number of stored primes */
    static idx_t last_k = 0;            /* last k that was examined */

    /* nothing required for n == 0 as sequence offset is 1 */
    if (n == 0) return 0;

    /* Ensure cache can hold at least n elements */
    ensure_capacity((size_t)n, &cap, (void **)&cache, sizeof(seq_t));

    /* Generate terms until we have at least n primes */
    while (len < n) {
        ++last_k;                      /* next consecutive pair k, k+1 */

        idx_t k1 = last_k;             /* first integer of the pair */
        idx_t k2 = k1 + 1;             /* second integer of the pair */

        /* Count digits of k2 in base 7 */
        idx_t t = k2;
        idx_t digits = 0;
        do {
            t /= 7;
            ++digits;
        } while (t > 0);

        /* Compute 7^digits */
        seq_t pow7 = 1;
        for (idx_t i = 0; i < digits; ++i) {
            pow7 *= 7;
        }

        /* Concatenated value: k1 * 7^digits + k2 */
        seq_t val = (seq_t)k1 * pow7 + (seq_t)k2;

        if (is_prime_big(val)) {
            cache[len++] = val;        /* store prime */
        }
    }

    return cache[n - 1];
}
